def find_magic_sequence(n=14, fixed=None):
    if fixed is None:
        fixed = {}

    x = [None] * n
    for i, v in fixed.items():
        x[i] = v

    fixed_set = set(fixed.keys())

    def recurse(k, count, current_sum):
        if k == n:
            for i in range(n):
                if x[i] != count[i]:
                    return False
            return True

        if k in fixed_set:
            v = x[k]
            new_count = list(count)
            if 0 <= v < n:
                new_count[v] += 1
            else:
                return False

            for i in range(k+1):
                if x[i] is not None:
                    needed = x[i] - new_count[i]
                    if needed < 0 or needed > n - k - 1:
                        return False

            new_sum = current_sum + v
            if new_sum > n:
                return False

            if recurse(k+1, tuple(new_count), new_sum):
                return True
            return False

        max_v = n - current_sum

        for v in range(max_v, -1, -1):
            new_count = list(count)
            if 0 <= v < n:
                new_count[v] += 1
            else:
                continue

            future_k = v - new_count[k]
            if future_k < 0 or future_k > n - k - 1:
                continue

            valid = True
            for i in range(k):
                if x[i] is not None:
                    future_i = x[i] - new_count[i]
                    if future_i < 0 or future_i > n - k - 1:
                        valid = False
                        break
            if not valid:
                continue

            remaining_sum = n - (current_sum + v)
            if remaining_sum < 0:
                continue

            x[k] = v
            if recurse(k+1, tuple(new_count), current_sum + v):
                return True
            x[k] = None

        return False

    initial_count = tuple([0] * n)
    if recurse(0, initial_count, 0):
        return x
    else:
        return None

seq = find_magic_sequence(14, fixed={11:0, 12:0})
print(seq)
